using System.Text.Json;
namespace HomeLibrary;
public static class AccountEndpoints {
 const string Cookie="__Host-hl-reader";
 static string Session(HttpContext c){var key=c.Request.Cookies.Keys.FirstOrDefault(k=>k.Equals(Cookie,StringComparison.Ordinal));return key==null?"":c.Request.Cookies[key]??"";}
 internal static BorrowerAccount Account(HttpContext c,BorrowerAccounts accounts)=>accounts.Resolve(Session(c))??throw new LibraryError("Sign in to your borrower account.",401);
 static void SetSession(HttpContext c,string token)=>c.Response.Cookies.Append(Cookie,token,new CookieOptions{HttpOnly=true,Secure=true,SameSite=SameSiteMode.Strict,Path="/",MaxAge=TimeSpan.FromDays(1),IsEssential=true});
 static object PersonalView(BorrowerAccount a,Store store,BorrowerVault vault){var view=JsonSerializer.SerializeToElement(store.AccountView(a),Library.Json);var fields=view.Deserialize<Dictionary<string,JsonElement>>(Library.Json)!;fields["entries"]=JsonSerializer.SerializeToElement(Array.Empty<object>());fields["vaultAccountId"]=JsonSerializer.SerializeToElement(a.Id);fields["vaultReady"]=JsonSerializer.SerializeToElement(vault.Exists(a.Id));fields["legacyPending"]=JsonSerializer.SerializeToElement(store.Read().State.ReadingEntries.Any(e=>e.ReaderId==a.ReaderId));return fields;}
 public static void Map(WebApplication app,Settings settings,Store store,Func<HttpContext,bool> admin,Func<HttpContext,bool> mobile){
  foreach(var prefix in new[]{"/api","/mobile"}){
   bool Allowed(HttpContext c)=>prefix=="/api"?admin(c):mobile(c);
   app.MapGet(prefix+"/accounts",(HttpContext c,BorrowerAccounts accounts)=>Allowed(c)?Results.Json(new{accounts=accounts.List()}):Results.NotFound());
   app.MapPost(prefix+"/accounts/approve",(AccountApproval input,HttpContext c,BorrowerAccounts accounts)=>{if(!Allowed(c))return Results.NotFound();return Results.Json(new{account=accounts.Approve(input,store),snapshot=store.AdminRead()},Library.Json);});
   app.MapPost(prefix+"/accounts/unblock",(JsonElement input,HttpContext c,BorrowerAccounts accounts)=>{if(!Allowed(c))return Results.NotFound();return Results.Json(new{account=accounts.Unblock(input.GetProperty("accountId").GetString()??"")});});
   app.MapPost(prefix+"/accounts/block",(JsonElement input,HttpContext c,BorrowerAccounts accounts,ReadingAccess access,PushNotifications push)=>{if(!Allowed(c))return Results.NotFound();var account=accounts.Get(input.GetProperty("accountId").GetString()??"");accounts.Block(account.Id);push.RemoveOwner("borrower:"+account.Id);if(account.ReaderId!="")access.Change(account.ReaderId,"disable");return Results.Ok(new{blocked=true});});
   app.MapPost(prefix+"/accounts/deletion-preview",(AccountDeletionInput input,HttpContext c,BorrowerAccounts accounts)=>{if(!Allowed(c))return Results.NotFound();return Results.Json(store.PreviewAccountDeletion(accounts.Get(input.AccountId),input,accounts.List()) with{ReadingEntries=0},Library.Json);});
   app.MapPost(prefix+"/accounts/delete",async(AccountDeletionInput input,HttpContext c,BorrowerAccounts accounts,ReadingAccess access,Reminders reminders,PushNotifications push,BorrowerVault vault)=>{if(!Allowed(c))return Results.NotFound();using var paused=await reminders.Pause(c.RequestAborted);var result=accounts.Delete(input,store,access,reminders);push.RemoveOwner("borrower:"+input.AccountId);return Results.Json(vault.AfterDeletion(result,input.AccountId,accounts),Library.Json);});
   app.MapPost(prefix+"/accounts/reset",(JsonElement input,HttpContext c,BorrowerAccounts accounts,BorrowerVault vault)=>{if(!Allowed(c))return Results.NotFound();var target=accounts.Get(input.GetProperty("accountId").GetString()??"");if(store.Read().State.ReadingEntries.Any(e=>e.ReaderId==target.ReaderId))throw new LibraryError("This account has personal records awaiting encryption. Librarian-issued reset links cannot open those records.",403);if(settings.PublicCatalogOrigin=="")throw new LibraryError("Configure public HTTPS sharing first.");return Results.Json(new{url=accounts.ResetLink(input.GetProperty("accountId").GetString()??"",settings.PublicCatalogOrigin)});}).RequireRateLimiting("account-reset-issue");
  }
  bool Public(HttpContext c)=>c.Connection.LocalPort==settings.CatalogPort&&settings.PublicCatalogOrigin!="";
  app.MapPost("/account/registration-options",(RegistrationOptionsRequest input,HttpContext c,Sharing sharing,RegistrationProtection protection)=>!Public(c)||!sharing.Allowed(input.ShareToken??"")?Results.NotFound():Results.Json(protection.Options())).RequireRateLimiting("personal-reading");
  app.MapPost("/account/register",async(AccountRegistration input,HttpContext c,BorrowerAccounts accounts,Sharing sharing,RegistrationProtection protection)=>{if(!Public(c)||!sharing.Allowed(input.ShareToken??""))return Results.NotFound();await protection.Verify(input.ChallengeToken,c.Connection.RemoteIpAddress,c.RequestAborted);var a=accounts.Register(input);SetSession(c,accounts.Session(a.Id));return Results.Json(new{account=a});}).RequireRateLimiting("account-register");
  app.MapPost("/account/login",(AccountLogin input,HttpContext c,BorrowerAccounts accounts)=>{if(!Public(c))return Results.NotFound();SetSession(c,accounts.Login(input));return Results.Ok(new{signedIn=true});}).RequireRateLimiting("account-login");
  app.MapPost("/account/logout",(HttpContext c,BorrowerAccounts accounts)=>{if(!Public(c))return Results.NotFound();accounts.Logout(Session(c));c.Response.Cookies.Delete(Cookie,new CookieOptions{Path="/",Secure=true,HttpOnly=true,SameSite=SameSiteMode.Strict});return Results.Ok(new{signedOut=true});});
  app.MapPost("/account/reset",(AccountReset input,HttpContext c,BorrowerAccounts accounts)=>{if(!Public(c))return Results.NotFound();accounts.Reset(input);c.Response.Cookies.Delete(Cookie,new CookieOptions{Path="/",Secure=true,HttpOnly=true,SameSite=SameSiteMode.Strict});return Results.Ok(new{reset=true});}).RequireRateLimiting("account-reset");
  app.MapGet("/account/about/{copyId}",async(string copyId,HttpContext c,BorrowerAccounts accounts,BookAbout about)=>{if(!Public(c))return Results.NotFound();var a=Account(c,accounts);if(a.Status!="active")throw new LibraryError("Your account needs approval.",403);var book=store.Read().State.Books.Find(b=>b.Id==copyId&&!b.Archived);return book==null?Results.NotFound():Results.Json(await about.Find(book,c.RequestAborted),Library.Json);}).RequireRateLimiting("personal-reading");
  app.MapGet("/account/me",(HttpContext c,BorrowerAccounts accounts)=>Public(c)?Results.Json(new{account=Account(c,accounts)}):Results.NotFound()).RequireRateLimiting("personal-reading");
  app.MapGet("/account/state",(HttpContext c,BorrowerAccounts accounts,BorrowerVault vault)=>Public(c)?Results.Json(PersonalView(Account(c,accounts),store,vault),Library.Json):Results.NotFound()).RequireRateLimiting("personal-reading");
  app.MapPost("/account/action",(ActionRequest input,HttpContext c,BorrowerAccounts accounts,BorrowerVault vault)=>{if(!Public(c))return Results.NotFound();if(input.Action is "saveReading" or "removeReading")throw new LibraryError("Unlock your encrypted personal list to change reading records.",403);var account=Account(c,accounts);store.AccountAction(account,input);return Results.Json(PersonalView(account,store,vault),Library.Json);}).RequireRateLimiting("personal-reading");
  app.MapPost("/account/requests",(PublicBookRequest input,HttpContext c,BorrowerAccounts accounts)=>{if(!Public(c))return Results.NotFound();return Results.Json(store.AccountRequest(Account(c,accounts),input),Library.Json);}).RequireRateLimiting("book-requests");
  app.MapGet("/account/{**leaf}",(string? leaf,HttpContext c,RegistrationProtection protection)=>{if(!Public(c))return Results.NotFound();if(leaf=="library-icon-192.png")return LibraryAppearance.IconFile(store,192,app.Environment.ContentRootPath);if(leaf=="library-icon-512.png")return LibraryAppearance.IconFile(store,512,app.Environment.ContentRootPath);if(leaf=="branding"){var state=store.Read().State;return Results.Json(new{libraryName=state.LibraryName,libraryTheme=LibraryAppearance.Theme(state),customIcon=state.LibraryIcon512!=""});}if(leaf=="manifest.webmanifest")return BorrowerApp.Manifest(store);if(leaf=="borrower-sw.js")c.Response.Headers["Service-Worker-Allowed"]="/";var file=leaf switch{null or ""=>"account.html","launch"=>"borrower-launch.html","borrower-theme.js"=>"borrower-theme.js","borrower-theme.css"=>"borrower-theme.css","borrower-launch.js"=>"borrower-launch.js","borrower-install.js"=>"borrower-install.js","borrower-sw.js"=>"borrower-sw.js","borrower-icon-192.png"=>"borrower-icon-192.png","borrower-icon-512.png"=>"borrower-icon-512.png","account.js"=>"account.js","book-about.js"=>"book-about.js","push-client.js"=>"push-client.js","reading.js"=>"reading.js","reading-list.js"=>"reading-list.js","history-controls.js"=>"history-controls.js","private-vault.js"=>"private-vault.js","vault-crypto.js"=>"vault-crypto.js","styles.css"=>"styles.css","cover-credit.js"=>"cover-credit.js","powered-by-google.png"=>"powered-by-google.png",_=>null};if(file==null)return Results.NotFound();c.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self'"+(protection.Enabled?" https://challenges.cloudflare.com":"")+"; frame-src "+(protection.Enabled?"https://challenges.cloudflare.com":"'none'")+"; style-src 'self' 'unsafe-inline'; img-src 'self' https:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'";return Results.File(Path.Combine(app.Environment.ContentRootPath,"wwwroot",file),file.EndsWith(".html")?"text/html":file.EndsWith(".js")?"text/javascript":file.EndsWith(".png")?"image/png":"text/css");});
 }
}
